window.ARCHIVE_ROOMS={"1":{"id":1,"name":"Galeria da Maré Oblíqua","xy":[312,72],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Galeria lateral de circulação e observação.","Descrição":"Marcas de maré sobem pelas paredes em ângulos impossíveis; placas ósseas formam um corredor que parece mais fundo do que é.","Pressão / Encontro":"Kappa-Escribas podem reescrever o piso molhado para transformá-lo em terreno difícil, cobertura ilusória ou armadilha de escorregão.","Pista concreta (sem teste)":"Algumas marcas de maré param abruptamente como se a água tivesse obedecido a uma ordem antiga.","Interações relevantes":"As placas ósseas podem ser giradas. Quando três marcas de maré são alinhadas, a corrente da galeria muda de direção por 10 minutos e revela sulcos que apontam para as salas 2 e 14.","Tesouro / recompensa":"Astrolábio da Maré Oblíqua (item incomum, 3 cargas). Como ação bônus, gaste 1 carga para ignorar terreno difícil causado por água e receber deslocamento de natação igual ao deslocamento terrestre por 10 minutos. Recupera 1d3 cargas ao amanhecer submerso.","Colecionável":"Selo da Foz I — um disco de bronze torto, gravado com uma ponte de Gualápoles. Valor: 150 PO.","Armadilha de ilusão":"A galeria parece continuar em linha reta, embora dobre. Investigação CD 16 percebe que as bolhas seguem a gravidade verdadeira. Falha: o grupo retorna à mesma porta e cada criatura perde 10 minutos."},"doors":[{"to":2,"face":"Leste · P1","attrs":"trancada (CD 15 para destrancar); madeira simples; CD 15 para arrombar; 10 PV; desliza lateralmente","status":"Intacta conforme o mapa original.","id":"P1","broken":false,"secret":false,"trap":false,"dc":15},{"to":2,"face":"Leste · P2","attrs":"secreta (CD 20 para encontrar); armadilhada; trancada (CD 15 para destrancar); ferro; CD 30 para arrombar; 60 PV","status":"Intacta conforme o mapa original.","id":"P2","broken":false,"secret":true,"trap":true,"dc":15},{"to":14,"face":"Sul · P3","attrs":"trancada (CD 20 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P3","broken":false,"secret":false,"trap":false,"dc":20}]},"2":{"id":2,"name":"Tábuas dos Nomes Lavados","xy":[392,40],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Armazenamento de registros deteriorados.","Descrição":"Tábuas de osso e madeira negra empilhadas; quase todos os nomes foram raspados, lavados ou corroídos.","Pressão / Encontro":"As tábuas às vezes devolvem o nome de um PJ em voz alheia; um teste de Sabedoria pode ser necessário para não seguir uma pista falsa.","Pista concreta (sem teste)":"Uma coluna de registros menciona títulos de travessia e direitos da foz, mas não linhagens nobres shadow fey.","Interações relevantes":"Esfregar sal nas tábuas faz nomes apagados reaparecerem por alguns segundos. Três nomes pertencem a famílias ainda existentes em Shadar-Riverie.","Tesouro / recompensa":"Tábua do Nome Restituído. Uma vez, pode restaurar magicamente um nome apagado de um documento, lápide ou memória escrita. Colecionadores pagariam 400 PO.","Colecionável":"4 Moedas dos Mortos Afogados e Selo da Foz II.","Armadilha de ilusão":"A sala tenta apagar o nome de quem lê em voz alta. Sabedoria CD 16; falha: por 1 hora, a criatura não consegue dizer o próprio nome e tem desvantagem contra efeitos de encantamento."},"doors":[{"to":3,"face":"Leste · P4","attrs":"trancada (CD 10 para destrancar); madeira simples; CD 15 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P4","broken":false,"secret":false,"trap":false,"dc":10},{"to":1,"face":"Sul · P5","attrs":"armadilhada; trancada (CD 10 para destrancar); pedra; CD 25 para arrombar; 60 PV","status":"Intacta conforme o mapa original.","id":"P5","broken":false,"secret":false,"trap":true,"dc":10},{"to":1,"face":"Oeste · P2","attrs":"secreta (CD 20 para encontrar); armadilhada; trancada (CD 15 para destrancar); ferro; CD 30 para arrombar; 60 PV","status":"Intacta conforme o mapa original.","id":"P2","broken":false,"secret":true,"trap":true,"dc":15}]},"3":{"id":3,"name":"Nicho de Gualápoles","xy":[488,56],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Memorial residual da cidade afundada.","Descrição":"Pequeno nicho com mosaico semi-submerso mostrando canais, pontes e torres de uma cidade anterior à Boca do Abismo.","Pressão / Encontro":"Visão breve do afundamento; quem tocar o mosaico vê a cidade descer e ouve o grito do antigo guardião.","Pista concreta (sem teste)":"Fica claro que o afundamento foi um gesto deliberado, não um acidente ou simples punição divina.","Interações relevantes":"O mosaico é um mapa parcial de Gualápoles. Pressionar o porto, o tribunal e a foz revela uma projeção aquática com rotas antigas.","Tesouro / recompensa":"Tessela de Gualápoles. Enquanto portada, concede vantagem em um teste de História ou Investigação relacionado à cidade afogada por descanso longo.","Colecionável":"Selo da Foz III e um fragmento de azulejo de madrepérola (250 PO).","Armadilha de ilusão":"O mosaico mostra a cidade intacta e convida o observador a entrar. Inteligência CD 17 para perceber a perspectiva impossível; falha: fica enfeitiçado por 1 minuto, tentando atravessar a parede."},"doors":[{"to":4,"face":"Leste · P8","attrs":"secreta (CD 15 para encontrar); emperrada; madeira reforçada; CD 15 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P8","broken":false,"secret":true,"trap":false,"dc":12},{"to":7,"face":"Sul · P6","attrs":"armadilhada; emperrada; ferro; CD 25 para arrombar; 60 PV","status":"Intacta conforme o mapa original.","id":"P6","broken":false,"secret":false,"trap":true,"dc":12},{"to":6,"face":"Sul · P7","attrs":"trancada (CD 10 para destrancar); ferro; CD 30 para arrombar; 60 PV","status":"Intacta conforme o mapa original.","id":"P7","broken":false,"secret":false,"trap":false,"dc":10},{"to":2,"face":"Oeste · P4","attrs":"trancada (CD 10 para destrancar); madeira simples; CD 15 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P4","broken":false,"secret":false,"trap":false,"dc":10}]},"4":{"id":4,"name":"Poço do Reflexo Curvo","xy":[584,56],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Poço de observação e distorção.","Descrição":"Água negra imóvel no centro; rostos refletidos sorriem fora de hora ou mostram marcas que o corpo real não tem.","Pressão / Encontro":"Ataques, magias ou fala diante do poço podem ser duplicados por ilusão menor atrasada, confundindo ordem de ação.","Pista concreta (sem teste)":"O reflexo da Jorō pode aparecer aqui muito antes de ela estar fisicamente próxima.","Interações relevantes":"Uma pedra pode ser lançada no poço para mostrar o reflexo de uma sala adjacente escolhida, mas também revela quem observa ao poço.","Tesouro / recompensa":"Frasco de Água de Reflexo Curvo (2 doses). Uma dose permite lançar Ver o Invisível por 10 minutos.","Colecionável":"Máscara de Laca “O Sorriso Tardio”, peça de coleção (300 PO).","Armadilha de ilusão":"O reflexo antecipa uma morte possível. Sabedoria CD 17; falha: amedrontado por 1 minuto. Sucesso: vantagem no próximo teste de resistência contra medo no Arquivo."},"doors":[{"to":8,"face":"Leste · P9","attrs":"trancada (CD 15 para destrancar); madeira simples; CD 15 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P9","broken":false,"secret":false,"trap":false,"dc":15},{"to":3,"face":"Oeste · P8","attrs":"secreta (CD 15 para encontrar); emperrada; madeira reforçada; CD 15 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P8","broken":false,"secret":true,"trap":false,"dc":12}]},"5":{"id":5,"name":"Câmara dos Escribas Afogados","xy":[216,88],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Oficina viva dos Kappa-Escribas.","Descrição":"Ferramentas de gravação, potes de tinta ritual e suportes de osso boiam em arranjos ainda funcionais.","Pressão / Encontro":"2 × Kappa-Escribas Afogados (CR 7 cada) ou vestígios recentes de trabalho deles.","Pista concreta (sem teste)":"Os sinais gravados aqui distinguem ‘domínio’, ‘passagem’ e ‘dignidade’; a Lança parece ligada aos três.","Interações relevantes":"Os Kappa-Escribas trocam informação por tinta, nomes verdadeiros ou moedas antigas. Uma bancada ainda permite copiar placas sem destruí-las.","Tesouro / recompensa":"Estojo do Escriba Afogado, ferramentas de calígrafo +1. Uma vez por dia, copia uma página inteira em 1 minuto, inclusive escrita mágica não protegida.","Colecionável":"3 potes de tinta ritual (75 PO cada) e Selo da Foz IV.","Armadilha de ilusão":"Um escriba ilusório pede assinatura. Quem assina sem ler sofre 4d6 psíquico e fica marcado pelo Arquivo até o próximo descanso longo. Investigação CD 15 revela cláusulas móveis."},"doors":[{"to":10,"face":"Sul · P11","attrs":"secreta (CD 20 para encontrar); armadilhada; destrancada; madeira de boa qualidade; 15 PV","status":"Intacta conforme o mapa original.","id":"P11","broken":false,"secret":true,"trap":true,"dc":0},{"to":9,"face":"Sul · P12","attrs":"armadilhada; destrancada; pedra; 60 PV","status":"Intacta conforme o mapa original.","id":"P12","broken":false,"secret":false,"trap":true,"dc":0}]},"6":{"id":6,"name":"Escada do Fôlego Roubado","xy":[408,152],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Ligação vertical entre setores secos e alagados.","Descrição":"Escada estreita, coberta de limo; subir ou descer aqui dá a sensação errada de estar prendendo a respiração.","Pressão / Encontro":"Quem correr pela escada sem atenção pode sofrer afogamento onírico temporário e perder ação bônus ou reação.","Pista concreta (sem teste)":"Uma inscrição parcial sugere: ‘a água toma primeiro o sopro de quem mente ao lugar’.","Interações relevantes":"Cada degrau rouba uma palavra de uma respiração. Pronunciar uma memória feliz estabiliza a escada e impede que ela se alongue.","Tesouro / recompensa":"Concha do Fôlego Roubado. Reação, 1/dia: quando falhar em teste contra sufocamento, gás ou veneno inalado, transforma em sucesso.","Colecionável":"7 pequenas contas de coral funerário (20 PO cada).","Armadilha de ilusão":"A escada parece interminável. Constituição CD 16; falha: ganha 1 nível de exaustão ilusória, removido ao sair da sala ou com ação de um aliado para lembrar seu destino."},"doors":[{"to":3,"face":"Norte · P7","attrs":"trancada (CD 10 para destrancar); ferro; CD 30 para arrombar; 60 PV","status":"Intacta conforme o mapa original.","id":"P7","broken":false,"secret":false,"trap":false,"dc":10},{"to":14,"face":"Sul · P13","attrs":"armadilhada; emperrada; madeira simples; CD 10 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P13","broken":false,"secret":false,"trap":true,"dc":12}]},"7":{"id":7,"name":"Sala das Máscaras de Laca","xy":[504,136],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Câmara de teste identitário yokai.","Descrição":"Máscaras quebradas, belas e cruéis, pendem de fios quase invisíveis; algumas choram água clara.","Pressão / Encontro":"Vestir ou quebrar máscaras provoca visões de si mesmo servindo a elfos, demônios ou algo pior.","Pista concreta (sem teste)":"As máscaras não foram feitas para ocultar rosto, mas para revelar qual papel alguém aceitaria ocupar.","Interações relevantes":"Vestir uma máscara faz o Arquivo responder com uma identidade possível. Algumas máscaras abrem rotas; outras atraem testemunhas.","Tesouro / recompensa":"Máscara de Laca da Segunda Face. 1/dia, permite lançar Disfarçar-se; enquanto submerso, a CD para perceber o disfarce aumenta em 2.","Colecionável":"Conjunto de três máscaras intactas (900 PO o conjunto).","Armadilha de ilusão":"Uma máscara tenta substituir o rosto do usuário. Carisma CD 17; falha: incapaz de removê-la por 1 hora e fala com a personalidade nela gravada."},"doors":[{"to":3,"face":"Norte · P6","attrs":"armadilhada; emperrada; ferro; CD 25 para arrombar; 60 PV","status":"Intacta conforme o mapa original.","id":"P6","broken":false,"secret":false,"trap":true,"dc":12},{"to":8,"face":"Leste · P14","attrs":"armadilhada; destrancada; madeira simples; 10 PV","status":"Intacta conforme o mapa original.","id":"P14","broken":false,"secret":false,"trap":true,"dc":0},{"to":11,"face":"Sul · P15","attrs":"trancada (CD 15 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P15","broken":false,"secret":false,"trap":false,"dc":15}]},"8":{"id":8,"name":"Registro das Correntes","xy":[616,136],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Contabilidade ritual da travessia e das cargas.","Descrição":"Correntes grossas cruzam a sala, prendendo placas antigas de jurisdição, tributo e passagem.","Pressão / Encontro":"Lampreias podem usar as correntes como rota de ataque; magias de teleporte podem sair alguns metros erradas aqui.","Pista concreta (sem teste)":"Ulorian herdou o uso da foz, mas não sua linguagem originária.","Interações relevantes":"As correntes podem ser reposicionadas para bloquear portas, criar linhas de segurança ou abrir um cofre preso ao teto.","Tesouro / recompensa":"Elo de Jurisdição. Como ação, fixa-se a uma superfície e funciona como Bastão Imóvel por até 10 minutos, 1/dia.","Colecionável":"Selo da Foz V e 60 PO em anéis de prata fluvial.","Armadilha de ilusão":"As correntes parecem agarrar quem carrega objetos roubados. Destreza CD 16; falha: restringido até usar ação e Atletismo CD 16."},"doors":[{"to":4,"face":"Norte · P16","attrs":"trancada (CD 25 para destrancar); madeira simples; CD 15 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P16","broken":false,"secret":false,"trap":false,"dc":25},{"to":12,"face":"Sul · P17","attrs":"secreta (CD 25 para encontrar); emperrada; pedra; CD 20 para arrombar; 60 PV","status":"Intacta conforme o mapa original.","id":"P17","broken":false,"secret":true,"trap":false,"dc":12},{"to":7,"face":"Oeste · P14","attrs":"armadilhada; destrancada; madeira simples; 10 PV","status":"Intacta conforme o mapa original.","id":"P14","broken":false,"secret":false,"trap":true,"dc":0}]},"9":{"id":9,"name":"Antessala do Sopro Falso","xy":[184,168],"fields":{"Estado hídrico":"Não completamente submersa. Antessala com passarelas, bordas pisáveis e lâmina d’água suficiente para visão da barreira e da Jorō.","Função":"Antessala ocidental da Câmara da Lança.","Descrição":"Através da água e da barreira da sala 13, a Jorō e a Lança podem ser vistas, mas a voz não atravessa. O ambiente parece convidar ao trato, não ao ataque.","Pressão / Encontro":"Se esta for a primeira antessala alcançada, Veren Marés-Rubras aparece aqui com sua oferta: descanso em Shadowfade, aliança provisória contra a aranha e promessa de sobrevivência.","Pista concreta (sem teste)":"Sem o Berrante Aquático, a antessala é um teatro mudo: ver a Jorō é fácil; falar com ela é impossível.","Interações relevantes":"A barreira da sala 13 responde a batidas rítmicas na parede, mas não transmite palavras. Um padrão de três batidas recebe três de volta.","Tesouro / recompensa":"Diapasão de Água Muda. Detecta barreiras mágicas em 9 m e vibra quando uma delas pode ser aberta por som.","Colecionável":"Fragmento do Juramento I.","Armadilha de ilusão":"Uma voz de Jorō parece convidar o grupo a atravessar uma passagem inexistente. Investigação CD 18; falha: 4d8 psíquico ao colidir com a barreira."},"doors":[{"to":5,"face":"Norte · P12","attrs":"armadilhada; destrancada; pedra; 60 PV","status":"Intacta conforme o mapa original.","id":"P12","broken":false,"secret":false,"trap":true,"dc":0},{"to":13,"face":"Sul · P19","attrs":"secreta (CD 15 para encontrar); destrancada; madeira reforçada; 20 PV","status":"Intacta conforme o mapa original.","id":"P19","broken":false,"secret":true,"trap":false,"dc":0}]},"10":{"id":10,"name":"Alfarrábio das Marés","xy":[264,200],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Depósito de fórmulas ligadas a corrente e refluxo.","Descrição":"Prateleiras inclinadas com placas dobradas pela água; algumas fórmulas parecem mais musicais que textuais.","Pressão / Encontro":"Um erro de leitura pode inverter correnteza local ou abrir passagem curta para água profunda.","Pista concreta (sem teste)":"Menciona-se um instrumento de chamada hidráulica, não pelo nome, mas como algo que ‘faz o arquivo ouvir’ — o berrante.","Interações relevantes":"As fórmulas podem alterar uma corrente em uma sala adjacente por 1 hora quando lidas como música.","Tesouro / recompensa":"Placa de Refluxo, pergaminho reutilizável 1/dia de Controlar Água, mas apenas para redirecionar corrente em um cubo de 6 m.","Colecionável":"Coleção de fórmulas gravadas (600 PO para um arcanista).","Armadilha de ilusão":"A leitura errada inverte direita e esquerda. Inteligência CD 16; falha: desvantagem no próximo teste de Destreza e pode escolher a porta errada se agir com pressa."},"doors":[{"to":5,"face":"Norte · P11","attrs":"secreta (CD 20 para encontrar); armadilhada; destrancada; madeira de boa qualidade; 15 PV","status":"Intacta conforme o mapa original.","id":"P11","broken":false,"secret":true,"trap":true,"dc":0},{"to":14,"face":"Leste · P21","attrs":"trancada (CD 25 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P21","broken":false,"secret":false,"trap":false,"dc":25}]},"11":{"id":11,"name":"Câmara das Testemunhas","xy":[504,216],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Arquivo de presença e juramento.","Descrição":"Corpos afogados sentados como escrivães ou magistrados ainda guardam posição em silêncio ritual.","Pressão / Encontro":"As testemunhas não atacam sempre; podem apontar para mentira, pactos ocultos ou nomes omitidos.","Pista concreta (sem teste)":"Elas reconhecem que o posto do Senhor do Rio existe, mas o tratam como incompleto e mal compreendido.","Interações relevantes":"Os corpos respondem a uma pergunta cada, desde que o consulente declare nome e intenção.","Tesouro / recompensa":"Olho de Testemunha em âmbar. 1/dia, vantagem num teste de Intuição; depois mostra uma lembrança desconfortável do alvo.","Colecionável":"Selo da Foz VI e 5 insígnias judiciais (50 PO cada).","Armadilha de ilusão":"Uma testemunha acusa falsamente um personagem de traição. Sabedoria CD 17; falha: não pode receber ajuda desse aliado por 1 minuto."},"doors":[{"to":7,"face":"Norte · P15","attrs":"trancada (CD 15 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P15","broken":false,"secret":false,"trap":false,"dc":15},{"to":12,"face":"Leste · P24","attrs":"trancada (CD 10 para destrancar); pedra; CD 25 para arrombar; 60 PV","status":"Intacta conforme o mapa original.","id":"P24","broken":false,"secret":false,"trap":false,"dc":10},{"to":19,"face":"Sul · P22","attrs":"secreta (CD 15 para encontrar); destrancada; madeira simples; 10 PV","status":"Intacta conforme o mapa original.","id":"P22","broken":false,"secret":true,"trap":false,"dc":0},{"to":20,"face":"Sul · P23","attrs":"trancada (CD 15 para destrancar); madeira simples; CD 15 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P23","broken":false,"secret":false,"trap":false,"dc":15}]},"12":{"id":12,"name":"Janela para Shadowfade","xy":[600,216],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Fissura estável de observação planar.","Descrição":"Um rasgo aquoso na parede mostra Shadowfade como um espelho mais escuro e mais verdadeiro do Arquivo.","Pressão / Encontro":"O grupo pode espiar, trocar rota ou sofrer intrusão mental. Demônios usam essa janela mais como isca do que como passagem franca.","Pista concreta (sem teste)":"Shadowfade preserva traços de trânsito yokai mais antigos que a ocupação demoníaca atual.","Interações relevantes":"A fissura mostra Shadowfade e, por instantes, caminhos fora do Arquivo. Pode servir para espionagem, mas algo observa de volta.","Tesouro / recompensa":"Lasca de Vidro Sombrio. Componente de 500 PO para magias planares ou foco que concede +1 em testes para identificar portais.","Colecionável":"Mapa em negativo de uma rua de Shadowfade.","Armadilha de ilusão":"O reflexo oferece uma saída imediata. Arcana CD 18 detecta que o portal termina no vazio. Entrar causa 6d6 força e devolve a criatura caída."},"doors":[{"to":8,"face":"Norte · P17","attrs":"secreta (CD 25 para encontrar); emperrada; pedra; CD 20 para arrombar; 60 PV","status":"Intacta conforme o mapa original.","id":"P17","broken":false,"secret":true,"trap":false,"dc":12},{"to":15,"face":"Leste · P26","attrs":"armadilhada; trancada (CD 20 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P26","broken":false,"secret":false,"trap":true,"dc":20},{"to":15,"face":"Leste · P27","attrs":"armadilhada; emperrada; madeira reforçada; CD 15 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P27","broken":false,"secret":false,"trap":true,"dc":12},{"to":20,"face":"Sul · P25","attrs":"armadilhada; emperrada; ferro; CD 25 para arrombar; 60 PV","status":"Intacta conforme o mapa original.","id":"P25","broken":false,"secret":false,"trap":true,"dc":12},{"to":11,"face":"Oeste · P24","attrs":"trancada (CD 10 para destrancar); pedra; CD 25 para arrombar; 60 PV","status":"Intacta conforme o mapa original.","id":"P24","broken":false,"secret":false,"trap":false,"dc":10}]},"13":{"id":13,"name":"Câmara da Lança da Perdição","xy":[152,264],"fields":{"Estado hídrico":"Não completamente submersa. Câmara central com núcleo ritual protegido, barreira ativa e água profunda ao redor, mas com área de sustentação/ritual visível.","Função":"Coração do Arquivo, fim do percurso e única câmara realmente final.","Descrição":"A Lança da Perdição repousa além de uma barreira ritual poderosa. Jorō Aracne dos Sonhos Afogados está aqui, guardando a Lança e julgando quem chega. A aranha e a barreira são visíveis das Rooms 9 e 17.","Pressão / Encontro":"A barreira só pode ser quebrada pela própria Jorō; força bruta, contramágica e truques comuns apenas fraturam efeitos periféricos. Sem Berrante Aquático não há comunicação direta confiável entre antessalas e Jorō.","Pista concreta (sem teste)":"A Lança não é só arma: é chave de domínio da foz, instrumento de negação e prova de que Gualápoles foi afundada para impedir herança ilegítima.","Interações relevantes":"A barreira responde a consentimento, chamada legítima e reconhecimento de Jorō. Força ou dissipação apenas reforçam as inscrições.","Tesouro / recompensa":"A Lança da Perdição, objetivo central. Seus poderes devem permanecer vinculados ao julgamento político e à autoridade sobre o Rio.","Colecionável":"O Selo da Foz XII está preso ao pedestal da Lança.","Armadilha de ilusão":"A sala cria uma falsa Lança ao alcance da mão. Investigação ou Religião CD 19. Tocar a cópia ativa 8d8 psíquico e revela uma ambição secreta em voz alta."},"doors":[{"to":9,"face":"Norte · P19","attrs":"secreta (CD 15 para encontrar); destrancada; madeira reforçada; 20 PV","status":"Intacta conforme o mapa original.","id":"P19","broken":false,"secret":true,"trap":false,"dc":0},{"to":17,"face":"Leste · P28","attrs":"trancada (CD 10 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P28","broken":false,"secret":false,"trap":false,"dc":10}]},"14":{"id":14,"name":"Sala das Tábuas Partidas","xy":[360,232],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Depósito danificado por impacto ou saque antigo.","Descrição":"Tábuas rituais quebradas boiam em água rasa, como se alguém tivesse tentado levar partes do Arquivo à força.","Pressão / Encontro":"Peças soltas podem formar pistas verdadeiras ou mentiras compostas pelas ilusões do lugar.","Pista concreta (sem teste)":"Há sinais claros de que demônios já vasculharam a sala procurando informação, não só tesouro.","Interações relevantes":"Fragmentos combinados formam trechos de um decreto anterior ao domínio élfico.","Tesouro / recompensa":"Tábua da Revogação Parcial. Uma vez, concede vantagem para dissipar ou contestar uma magia de juramento, geas ou contrato.","Colecionável":"2 fragmentos valiosos de osso-oráculo (300 PO cada).","Armadilha de ilusão":"As peças parecem completar uma mensagem diferente para cada leitor. Investigação CD 16 separa texto real de desejo."},"doors":[{"to":6,"face":"Norte · P13","attrs":"armadilhada; emperrada; madeira simples; CD 10 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P13","broken":false,"secret":false,"trap":true,"dc":12},{"to":1,"face":"Norte · P30","attrs":"trancada (CD 15 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P30","broken":false,"secret":false,"trap":false,"dc":15},{"to":10,"face":"Oeste · P21","attrs":"trancada (CD 25 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P21","broken":false,"secret":false,"trap":false,"dc":25}]},"15":{"id":15,"name":"Depósito das Âncoras Mortas","xy":[696,280],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Armazenamento pesado e ponto de emboscada.","Descrição":"Âncoras antigas, correntes, ferragens e pesos funerários jazem meio submersos em pilhas escuras.","Pressão / Encontro":"Morgat ou suas marcas podem aparecer aqui; é um bom setor para ruído, ruptura e luta de força.","Pista concreta (sem teste)":"As âncoras foram usadas não para conter navios, mas para fixar selos e pesos rituais no momento do afundamento.","Interações relevantes":"As âncoras podem servir como cobertura, armadilha improvisada ou contrapeso para abrir uma passagem vertical.","Tesouro / recompensa":"Âncora de Pulso Morto, arma improvisada mágica +1; 1/dia, ao acertar, impede teleporte do alvo até o fim do próximo turno.","Colecionável":"Corrente funerária de prata negra (500 PO).","Armadilha de ilusão":"Uma âncora parece prender o coração do alvo. Constituição CD 17; falha: deslocamento reduzido à metade e não pode usar reação por 1 minuto."},"doors":[{"to":12,"face":"Norte · P32","attrs":"secreta (CD 20 para encontrar); emperrada; madeira simples; CD 10 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P32","broken":false,"secret":true,"trap":false,"dc":12},{"to":27,"face":"Sul · P31","attrs":"armadilhada; trancada (CD 25 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P31","broken":false,"secret":false,"trap":true,"dc":25},{"to":12,"face":"Oeste · P27","attrs":"armadilhada; emperrada; madeira reforçada; CD 15 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P27","broken":false,"secret":false,"trap":true,"dc":12}]},"16":{"id":16,"name":"Corredor do Nome Esquecido","xy":[72,312],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Passagem de erosão simbólica.","Descrição":"Toda palavra dita aqui parece perder uma sílaba, um título ou uma certeza.","Pressão / Encontro":"Magias baseadas em palavra de comando, juramento ou identidade podem falhar ou sair torcidas.","Pista concreta (sem teste)":"Quem entende isso percebe por que o Arquivo é tão perigoso para nobres que dependem de títulos e legitimidade pública.","Interações relevantes":"Escrever um nome na parede impede que ele seja corroído durante a travessia.","Tesouro / recompensa":"Giz do Nome Inteiro, 6 usos. Um nome escrito não pode ser magicamente apagado por 24 horas.","Colecionável":"Selo da Foz VII.","Armadilha de ilusão":"Cada personagem ouve o próprio nome sendo esquecido por seus aliados. Sabedoria CD 16; falha: não pode conceder nem receber Inspiração por 1 hora."},"doors":[{"to":21,"face":"Leste · P34","attrs":"secreta (CD 25 para encontrar); destrancada; madeira reforçada; 20 PV","status":"Intacta conforme o mapa original.","id":"P34","broken":false,"secret":true,"trap":false,"dc":0},{"to":21,"face":"Oeste · P33","attrs":"secreta (CD 15 para encontrar); armadilhada; trancada (CD 20 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV; sobe verticalmente","status":"Intacta conforme o mapa original.","id":"P33","broken":false,"secret":true,"trap":true,"dc":20}]},"17":{"id":17,"name":"Antessala dos Ecos em Vigília","xy":[232,296],"fields":{"Estado hídrico":"Não completamente submersa. Antessala com bordas firmes, canais fundos e linha de visão para a Câmara da Lança.","Função":"Antessala oriental da Câmara da Lança.","Descrição":"Outra abertura de visão para a Room 13. A barreira e a Jorō são visíveis, mas a água, as camadas do véu e o silêncio ritual impedem conversa direta.","Pressão / Encontro":"Se esta for a primeira antessala alcançada, Veren Marés-Rubras aparece aqui com a mesma oferta de descanso em Shadowfade e aliança contra a aranha. Se o grupo já o encontrou na Room 9, ele retoma a conversa em tom mais urgente ou mais sedutor.","Pista concreta (sem teste)":"A diferença entre esta antessala e a 9 sugere que o Arquivo foi desenhado para ser abordado por múltiplas vias, não por uma rota única.","Interações relevantes":"A abertura permite observar Jorō e a Lança por outro ângulo. Gestos simbólicos ainda atravessam a barreira.","Tesouro / recompensa":"Luva da Linguagem sem Voz. Concede proficiência em uma forma ritual de sinais yokai enquanto usada.","Colecionável":"Fragmento do Juramento II.","Armadilha de ilusão":"Uma versão hostil de Jorō imita seus movimentos. Intuição CD 18 percebe que o reflexo não protege Mira."},"doors":[{"to":13,"face":"Norte · P36","attrs":"armadilhada; emperrada; madeira reforçada; CD 15 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P36","broken":false,"secret":false,"trap":true,"dc":12},{"to":18,"face":"Leste · P35","attrs":"armadilhada; destrancada; madeira de boa qualidade; 15 PV; reforçada magicamente; desvantagem para arrombar","status":"Intacta conforme o mapa original.","id":"P35","broken":false,"secret":false,"trap":true,"dc":0}]},"18":{"id":18,"name":"Piscina dos Sonhos Vazados","xy":[312,312],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Reservatório de sonho residual.","Descrição":"Água leitosa e fria; imagens de futuros possíveis ou passados não vividos surgem em sua superfície.","Pressão / Encontro":"Beber, tocar ou observar por tempo demais pode impor condição de confusão, fascinação ou conhecimento perigoso.","Pista concreta (sem teste)":"Entre as imagens possíveis está uma Carcaça onde o Sonho voltou — mas sem garantia de quem o trouxe.","Interações relevantes":"Tocar a água revela um sonho específico. Um personagem pode pedir passado, futuro ou desejo, mas não controla qual verdade receberá.","Tesouro / recompensa":"Pérola do Sonho Vazado. Consumível: lança Augúrio sem componente e sem chance cumulativa de resposta aleatória.","Colecionável":"6 ampolas de sonho preservado (100 PO cada).","Armadilha de ilusão":"O personagem vive um futuro feliz e deve escolher sair. Sabedoria CD 17; falha: incapacitado por 1 minuto, repetindo a cena."},"doors":[{"to":23,"face":"Leste · P39","attrs":"secreta (CD 20 para encontrar); trancada (CD 15 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV; desliza lateralmente","status":"Intacta conforme o mapa original.","id":"P39","broken":false,"secret":true,"trap":false,"dc":15},{"to":29,"face":"Sul · P37","attrs":"secreta (CD 20 para encontrar); emperrada; madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P37","broken":false,"secret":true,"trap":false,"dc":12},{"to":17,"face":"Oeste · P35","attrs":"armadilhada; destrancada; madeira de boa qualidade; 15 PV; reforçada magicamente; desvantagem para arrombar","status":"Intacta conforme o mapa original.","id":"P35","broken":false,"secret":false,"trap":true,"dc":0},{"to":22,"face":"Oeste · P38","attrs":"trancada (CD 15 para destrancar); pedra; CD 25 para arrombar; 60 PV; desliza lateralmente","status":"Intacta conforme o mapa original.","id":"P38","broken":false,"secret":false,"trap":false,"dc":15}]},"19":{"id":19,"name":"Galeria dos Afogados Sem Rosto","xy":[424,296],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Arquivo de perda e anonimato.","Descrição":"Figuras pendem em nichos rasos, com o rosto liso, apagado ou consumido pela água.","Pressão / Encontro":"A galeria reage a intrusos que escondem identidade ou trabalham sob documento falso.","Pista concreta (sem teste)":"Ela sugere que o Arquivo não é contra o disfarce em si, mas contra a submissão sem vontade própria.","Interações relevantes":"Recolocar uma máscara ou nome num afogado restaura uma lembrança curta.","Tesouro / recompensa":"Véu do Rosto Restituído. 1/dia, ao tocar um cadáver, mostra sua aparência em vida por 10 minutos.","Colecionável":"Selo da Foz VIII e broche de magistrado (350 PO).","Armadilha de ilusão":"Os rostos dos aliados desaparecem. Sabedoria CD 17; falha: não distingue amigos e inimigos além de 3 m por 1 minuto."},"doors":[{"to":11,"face":"Norte · P22","attrs":"secreta (CD 15 para encontrar); destrancada; madeira simples; 10 PV","status":"Intacta conforme o mapa original.","id":"P22","broken":false,"secret":true,"trap":false,"dc":0},{"to":23,"face":"Sul · P41","attrs":"armadilhada; destrancada; ferro; 60 PV","status":"Intacta conforme o mapa original.","id":"P41","broken":false,"secret":false,"trap":true,"dc":0},{"to":24,"face":"Sul · P42","attrs":"trancada (CD 10 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P42","broken":false,"secret":false,"trap":false,"dc":10}]},"20":{"id":20,"name":"Câmara da Voz Repetida","xy":[552,296],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Reverberação ritual e erro de comando.","Descrição":"Toda fala retorna mais de uma vez, e nem sempre igual ao original.","Pressão / Encontro":"Ordens táticas e conjurações verbais podem ser duplicadas por eco ilusório. Ótima sala para barganha demoníaca ou mal-entendido perigoso.","Pista concreta (sem teste)":"Uma frase do antigo guardião sobre ‘negar a herança à Corte’ pode ser ouvida fragmentada aqui.","Interações relevantes":"Uma frase repetida três vezes, cada vez corrigida, torna-se uma ordem menor obedecida pela sala: abrir, fechar, calar ou iluminar.","Tesouro / recompensa":"Caixa da Voz Repetida. Armazena até 10 palavras e pode reproduzi-las com a voz exata de quem falou.","Colecionável":"Cilindro fonográfico ritual (250 PO).","Armadilha de ilusão":"A sala repete uma ordem com uma palavra alterada. Inteligência CD 16; falha: usa reação para obedecer à versão falsa."},"doors":[{"to":11,"face":"Norte · P23","attrs":"trancada (CD 15 para destrancar); madeira simples; CD 15 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P23","broken":false,"secret":false,"trap":false,"dc":15},{"to":12,"face":"Norte · P25","attrs":"armadilhada; emperrada; ferro; CD 25 para arrombar; 60 PV","status":"Intacta conforme o mapa original.","id":"P25","broken":false,"secret":false,"trap":true,"dc":12},{"to":25,"face":"Sul · P43","attrs":"trancada (CD 20 para destrancar); madeira simples; CD 15 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P43","broken":false,"secret":false,"trap":false,"dc":20},{"to":26,"face":"Sul · P44","attrs":"secreta (CD 20 para encontrar); emperrada; madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P44","broken":false,"secret":true,"trap":false,"dc":12}]},"21":{"id":21,"name":"Claustro do Espelho Fundo","xy":[152,360],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Território favorito do Akaname.","Descrição":"Espelhos de água e placas polidas formam ângulos falsos e rotas que parecem elegantes demais para serem confiáveis.","Pressão / Encontro":"Akaname do Espelho Fundo (CR 10) ou seus efeitos de humilhação reflexiva.","Pista concreta (sem teste)":"O Akaname insiste em punir pressa e vulgaridade, reforçando que o Arquivo julga comportamento, não só poder bruto.","Interações relevantes":"Os espelhos podem mostrar rotas verdadeiras quando sujos com limo do Akaname, mas uma superfície limpa sempre mente.","Tesouro / recompensa":"Espelho do Fundo Honesto. 1/dia, revela uma criatura invisível refletida por 1 rodada.","Colecionável":"Máscara de Laca “O Limpador Faminto” (250 PO).","Armadilha de ilusão":"A saída mais elegante é falsa. Investigação CD 17; falha: entra num laço espacial e retorna com 2d6 psíquico."},"doors":[{"to":22,"face":"Leste · P46","attrs":"trancada (CD 15 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P46","broken":false,"secret":false,"trap":false,"dc":15},{"to":29,"face":"Sul · P48","attrs":"trancada (CD 10 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P48","broken":false,"secret":false,"trap":false,"dc":10},{"to":30,"face":"Sul · P49","attrs":"secreta (CD 15 para encontrar); destrancada; madeira reforçada; 20 PV","status":"Intacta conforme o mapa original.","id":"P49","broken":false,"secret":true,"trap":false,"dc":0},{"to":16,"face":"Oeste · P34","attrs":"secreta (CD 25 para encontrar); destrancada; madeira reforçada; 20 PV","status":"Intacta conforme o mapa original.","id":"P34","broken":false,"secret":true,"trap":false,"dc":0},{"to":16,"face":"Oeste · P47","attrs":"trancada (CD 25 para destrancar); pedra; CD 25 para arrombar; 60 PV","status":"Intacta conforme o mapa original.","id":"P47","broken":false,"secret":false,"trap":false,"dc":25}]},"22":{"id":22,"name":"Trono das Correntes Vazias","xy":[232,376],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Memória deformada do posto da foz.","Descrição":"Não é o trono verdadeiro, mas um lugar subsidiário ligado à administração da passagem e do comando das águas.","Pressão / Encontro":"Sentar aqui sem preparo pode gerar visões do posto do Senhor do Rio, da Rainha e do vazio entre ambos.","Pista concreta (sem teste)":"Ulorian ocupa uma função real, mas parcial: sente o poder do posto sem compreender a raiz yokai que o sustenta.","Interações relevantes":"Sentar no trono mostra quais correntes políticas prendem o ocupante.","Tesouro / recompensa":"Anel das Correntes Vazias. Vantagem em um teste de resistência contra ser enfeitiçado ou dominado por descanso longo.","Colecionável":"Selo da Foz IX.","Armadilha de ilusão":"O trono coroa o usuário como soberano. Carisma CD 18; falha: não abandona o assento voluntariamente por 1 minuto."},"doors":[{"to":18,"face":"Leste · P38","attrs":"trancada (CD 15 para destrancar); pedra; CD 25 para arrombar; 60 PV; desliza lateralmente","status":"Intacta conforme o mapa original.","id":"P38","broken":false,"secret":false,"trap":false,"dc":15},{"to":29,"face":"Leste · P50","attrs":"trancada (CD 20 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P50","broken":false,"secret":false,"trap":false,"dc":20},{"to":21,"face":"Oeste · P46","attrs":"trancada (CD 15 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P46","broken":false,"secret":false,"trap":false,"dc":15}]},"23":{"id":23,"name":"Antecâmara dos Registradores","xy":[392,360],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Setor de espera e triagem antiga.","Descrição":"Bancos, suportes e nichos parecem preparados para receber gente antes de decisões importantes.","Pressão / Encontro":"Um lugar bom para descansar mal, pois o Arquivo observa e ‘prepara’ quem insiste em tratar o complexo como simples repartição.","Pista concreta (sem teste)":"Há sinais de que o acesso à Lança já foi regulado por mérito ritual, não por linhagem aristocrática.","Interações relevantes":"Os bancos preservam fichas de espera. Algumas pertencem a pessoas ainda vivas.","Tesouro / recompensa":"Ficha de Prioridade Ancestral. Pode ser apresentada a um espírito burocrático para receber uma audiência imediata uma vez.","Colecionável":"12 fichas de madrepérola, 25 PO cada.","Armadilha de ilusão":"O grupo acredita que precisa esperar sua vez. Sabedoria CD 15; falha: perde 10 minutos em silêncio."},"doors":[{"to":19,"face":"Norte · P41","attrs":"armadilhada; destrancada; ferro; 60 PV","status":"Intacta conforme o mapa original.","id":"P41","broken":false,"secret":false,"trap":true,"dc":0},{"to":18,"face":"Oeste · P39","attrs":"secreta (CD 20 para encontrar); trancada (CD 15 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV; desliza lateralmente","status":"Intacta conforme o mapa original.","id":"P39","broken":false,"secret":true,"trap":false,"dc":15}]},"24":{"id":24,"name":"Tanque das Marés Negras","xy":[456,360],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Ninho parcial da influência de Gharoz.","Descrição":"Água pesada, negra e gorda, cheia de bolhas lentas e silêncio ruim.","Pressão / Encontro":"Lampreias do Pavor Abissal ou sinais recentes do próprio jacaré demoníaco.","Pista concreta (sem teste)":"Marcas de arrasto e mordida sugerem que algo enorme carrega consigo um objeto que o Arquivo reconheceria — o berrante.","Interações relevantes":"Bolhas grandes contêm lembranças de Gharoz e podem revelar onde ele passou recentemente.","Tesouro / recompensa":"Ampola de Maré Negra, 2 doses. Arremesso a 6 m: cria área de 3 m fortemente obscurecida por 1 minuto.","Colecionável":"Dente antigo de crocodilo demoníaco (300 PO).","Armadilha de ilusão":"A água parece segura e rasa. Percepção CD 18 percebe profundidade falsa; falha: alvo é puxado 6 m e sofre 3d8 necrótico."},"doors":[{"to":19,"face":"Norte · P42","attrs":"trancada (CD 10 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P42","broken":false,"secret":false,"trap":false,"dc":10},{"to":25,"face":"Leste · P51","attrs":"trancada (CD 15 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P51","broken":false,"secret":false,"trap":false,"dc":15},{"to":31,"face":"Sul · P52","attrs":"armadilhada; trancada (CD 15 para destrancar); ferro; CD 30 para arrombar; 60 PV; desliza lateralmente","status":"Intacta conforme o mapa original.","id":"P52","broken":false,"secret":false,"trap":true,"dc":15}]},"25":{"id":25,"name":"Câmara do Julgamento Raso","xy":[520,376],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Provação curta, mas incisiva.","Descrição":"Uma sala aparentemente simples, quase seca, que pesa nas escolhas morais mais que nas físicas.","Pressão / Encontro":"Quem jura lealdade imediata a demônios ou à Corte pode disparar punições mentais mais fortes aqui.","Pista concreta (sem teste)":"A neutralidade vazia não basta; o Arquivo parece buscar autonomia com direção, não ausência de vínculo.","Interações relevantes":"A sala apresenta uma escolha pequena e concreta. Cumpri-la honestamente fornece passagem segura e um benefício.","Tesouro / recompensa":"Peso da Escolha Clara. 1/dia, antes de rolar, declare um custo narrativo razoável para obter vantagem no teste.","Colecionável":"Fragmento do Juramento III.","Armadilha de ilusão":"A sala oferece uma opção sem custo. Intuição CD 17 revela a mentira; aceitar impõe desvantagem no próximo teste de resistência."},"doors":[{"to":20,"face":"Norte · P43","attrs":"trancada (CD 20 para destrancar); madeira simples; CD 15 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P43","broken":false,"secret":false,"trap":false,"dc":20},{"to":26,"face":"Leste · P54","attrs":"armadilhada; destrancada; madeira simples; 10 PV","status":"Intacta conforme o mapa original.","id":"P54","broken":false,"secret":false,"trap":true,"dc":0},{"to":24,"face":"Oeste · P51","attrs":"trancada (CD 15 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P51","broken":false,"secret":false,"trap":false,"dc":15}]},"26":{"id":26,"name":"Fenda do Véu Abissal","xy":[584,392],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Ruptura ativa para Shadowfade / Abismo sombreado.","Descrição":"O espaço rasga de modo úmido; a água parece escorrer para um lugar que não existe do lado físico.","Pressão / Encontro":"Bom ponto para retirada demoníaca, conversa traiçoeira, teleporte perigoso ou perseguição curta.","Pista concreta (sem teste)":"Os demônios não criaram esse atalho; eles o ocuparam depois de os yokai perderem ou retirarem o controle pleno da foz.","Interações relevantes":"A fenda pode ser selada temporariamente com luz radiante, sal consagrado ou uma memória voluntariamente sacrificada.","Tesouro / recompensa":"Caco do Véu Abissal, foco raro perigoso. +1 em ataques de magia contra corruptores, mas demônios sentem sua direção a 1 km.","Colecionável":"7 cristais de sombra salgada (50 PO cada).","Armadilha de ilusão":"Um aliado parece ser substituído por demônio. Sabedoria CD 18; falha: considera o aliado hostil até sofrer dano ou usar ação para reavaliar."},"doors":[{"to":20,"face":"Norte · P44","attrs":"secreta (CD 20 para encontrar); emperrada; madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P44","broken":false,"secret":true,"trap":false,"dc":12},{"to":25,"face":"Oeste · P54","attrs":"armadilhada; destrancada; madeira simples; 10 PV","status":"Intacta conforme o mapa original.","id":"P54","broken":false,"secret":false,"trap":true,"dc":0}]},"27":{"id":27,"name":"Armazém dos Sonhos Penhorados","xy":[648,392],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Depósito simbólico de aspirações interrompidas.","Descrição":"Objetos triviais — brinquedos, ferramentas, cartas, laços, peças de roupa — preservados como se valessem mais que ouro.","Pressão / Encontro":"Ilusões aqui oferecem exatamente o que cada intruso mais gostaria de recuperar.","Pista concreta (sem teste)":"Restauração de Gualápoles significava restaurar cidade, rio e futuro; não era só manter um posto de poder.","Interações relevantes":"Cada objeto revela o sonho de seu antigo dono. Devolver um objeto a alguém vivo pode criar um aliado.","Tesouro / recompensa":"Baú dos Sonhos Penhorados: contém 800 PO em joias pessoais, mas vender tudo marca o grupo como saqueadores perante o Arquivo.","Colecionável":"Selo da Foz X e 10 objetos identificáveis.","Armadilha de ilusão":"Um objeto assume a forma do maior desejo do observador. Sabedoria CD 17; falha: recusa-se a largá-lo por 10 minutos."},"doors":[{"to":15,"face":"Norte · P31","attrs":"armadilhada; trancada (CD 25 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P31","broken":false,"secret":false,"trap":true,"dc":25},{"to":32,"face":"Leste · P55","attrs":"armadilhada; destrancada; madeira reforçada; 20 PV","status":"Intacta conforme o mapa original.","id":"P55","broken":false,"secret":false,"trap":true,"dc":0}]},"28":{"id":28,"name":"Limiar do Consentimento","xy":[728,360],"fields":{"Estado hídrico":"Não completamente submersa. Escadaria de entrada, limiar e bordas iniciais ainda transitáveis antes da descida total para o Arquivo.","Função":"Entrada real do Arquivo; começo fixo da exploração.","Descrição":"Uma escadaria monumental desce dos canais até uma água que não acompanha a corrente externa. A parede leste está aberta por uma brecha irregular, larga o bastante para um tubarão gigante: blocos de pedra foram empurrados para dentro, marcas semicirculares de dentes cortam o reboco e o limo ainda flutua em pequenas nuvens quando alguém passa. No piso, seis anéis de água se formam quando o grupo retorna, registrando que o pacto de entrada já foi aceito.","Pressão / Encontro":"O Selo da Entrada Voluntária já reconheceu o grupo. As ilusões não precisam mais convencê-los a entrar; agora tentam fazê-los esquecer o que aceitaram. A brecha leste permite fuga rápida, mas também oferece uma rota óbvia para perseguidores.","Pista concreta (sem teste)":"Sem teste: a inscrição yokai sob o primeiro degrau repete a palavra equivalente a consentimento, não invasão. O Arquivo considera o grupo participante de um pacto, não simples saqueador.","Interações relevantes":"O aviso yokai foi pronunciado e aceito. Agora a sala reconhece o grupo: a água forma seis anéis quando eles retornam. A brecha leste feita na primeira invasão continua aberta, com pedras esmagadas e marcas de dentes de tubarão gigante.","Tesouro / recompensa":"Chave do Consentimento: uma placa de marfim fluvial presa sob o primeiro degrau. 1/dia, permite repetir um teste de resistência contra uma ilusão do Arquivo.","Colecionável":"Selo da Foz XI e 6 Moedas dos Mortos Afogados entre as pedras da brecha.","Armadilha de ilusão":"A saída leste parece intacta e segura, escondendo a brecha real. Investigação CD 16 ou tocar a parede revela a corrente atravessando o falso reboco. Falha: a criatura perde uma ação tentando abrir uma porta inexistente."},"doors":[{"to":32,"face":"Sul · P57","attrs":"trancada (CD 20 para destrancar); madeira simples; CD 15 para arrombar; 10 PV","status":"DESTRUÍDA pelo tubarão gigante; acesso 28–32 permanece aberto.","id":"P57","broken":true,"secret":false,"trap":false,"dc":20}]},"29":{"id":29,"name":"Ancoradouro Interno","xy":[312,424],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Cais interno e ponto de circulação material antiga.","Descrição":"Pequeno píer de pedra afundado; correntes, argolas e marcas de embarque sobrevivem sob o limo.","Pressão / Encontro":"Bom setor para pegadas, rastros falsos, passagem de minions e armadilha de água que sobe de repente.","Pista concreta (sem teste)":"O Arquivo era visitado e usado; não era um cofre secreto enterrado desde sempre.","Interações relevantes":"Argolas e marcas de calado permitem reconstituir que tipos de embarcação entravam no Arquivo.","Tesouro / recompensa":"Corda de Atracação Impossível, 15 m. Quando amarrada, não pode ser desatada por corrente ou movimento involuntário.","Colecionável":"Sino portuário de bronze (400 PO).","Armadilha de ilusão":"Um barco chega vazio e oferece passagem. Investigação CD 16; embarcar transporta os ocupantes de volta à sala 28, molhados e sem perceber."},"doors":[{"to":18,"face":"Norte · P37","attrs":"secreta (CD 20 para encontrar); emperrada; madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P37","broken":false,"secret":true,"trap":false,"dc":12},{"to":31,"face":"Leste · P58","attrs":"trancada (CD 15 para destrancar); madeira simples; CD 15 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P58","broken":false,"secret":false,"trap":false,"dc":15},{"to":36,"face":"Sul · P59","attrs":"secreta (CD 15 para encontrar); destrancada; madeira simples; 10 PV","status":"Intacta conforme o mapa original.","id":"P59","broken":false,"secret":true,"trap":false,"dc":0},{"to":22,"face":"Oeste · P50","attrs":"trancada (CD 20 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P50","broken":false,"secret":false,"trap":false,"dc":20},{"to":21,"face":"Oeste · P60","attrs":"secreta (CD 20 para encontrar); armadilhada; destrancada; madeira reforçada; 20 PV","status":"Intacta conforme o mapa original.","id":"P60","broken":false,"secret":true,"trap":true,"dc":0}]},"30":{"id":30,"name":"Salão do Guardião Afundado","xy":[120,424],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Memória central do gesto que condenou e preservou o Arquivo.","Descrição":"Estátua quebrada, restos de aparato ritual e marcas de violência mostram um lugar de decisão final.","Pressão / Encontro":"Visão forte do momento em que o guardião escolheu afundar o Arquivo com a Lança dentro.","Pista concreta (sem teste)":"O gesto foi traiçoeiro de propósito: punir a Rainha, negar o posto intacto e chamar a fome demoníaca contra um trono enfraquecido.","Interações relevantes":"A estátua responde a armas baixadas, não a ataques. Colocar uma arma diante dela revela o gesto que selou o Arquivo.","Tesouro / recompensa":"Escudo do Guardião Afundado +1. 1/dia, reação para receber metade do dano destinado a um aliado adjacente.","Colecionável":"Medalhão quebrado do último guardião (500 PO).","Armadilha de ilusão":"A estátua parece atacar primeiro. Intuição CD 17; quem reage violentamente ativa 5d8 força."},"doors":[{"to":21,"face":"Norte · P49","attrs":"secreta (CD 15 para encontrar); destrancada; madeira reforçada; 20 PV","status":"Intacta conforme o mapa original.","id":"P49","broken":false,"secret":true,"trap":false,"dc":0},{"to":33,"face":"Sul · P61","attrs":"armadilhada; trancada (CD 15 para destrancar); pedra; CD 25 para arrombar; 60 PV; desliza lateralmente","status":"Intacta conforme o mapa original.","id":"P61","broken":false,"secret":false,"trap":true,"dc":15}]},"31":{"id":31,"name":"Escarpa do Lago Interior","xy":[408,440],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Borda perigosa com rotas altas e baixas.","Descrição":"Queda abrupta para um lago interno profundo; passagens laterais permitem exploração ousada.","Pressão / Encontro":"Ótimo lugar para escalar, cair, fugir ou ser puxado por teia, corrente ou ilusão.","Pista concreta (sem teste)":"Daqui é possível intuir que muitas salas se conectam por vias não óbvias; o mapa do Arquivo é mais tridimensional do que parece.","Interações relevantes":"As rotas alta e baixa levam a ângulos diferentes. Cordas e âncoras permitem criar um atalho permanente.","Tesouro / recompensa":"Botas da Escarpa, item incomum: vantagem em Atletismo para nadar/escalar e ignora os primeiros 3 m de queda.","Colecionável":"Mapa topográfico em prata (300 PO).","Armadilha de ilusão":"A borda parece 1,5 m mais próxima. Percepção CD 17; falha: queda no lago interior, 4d6 contundente e separação."},"doors":[{"to":24,"face":"Norte · P52","attrs":"armadilhada; trancada (CD 15 para destrancar); ferro; CD 30 para arrombar; 60 PV; desliza lateralmente","status":"Intacta conforme o mapa original.","id":"P52","broken":false,"secret":false,"trap":true,"dc":15},{"to":29,"face":"Oeste · P58","attrs":"trancada (CD 15 para destrancar); madeira simples; CD 15 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P58","broken":false,"secret":false,"trap":false,"dc":15}]},"32":{"id":32,"name":"Oficina do Afogamento Ritual","xy":[728,424],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Setor onde afogamento e registro se tornavam uma mesma coisa.","Descrição":"Oito tanques de pedra formam duas linhas, cercados por cintas de bronze, etiquetas ósseas e tubos que ainda expelem bolhas. Não eram instrumentos de execução comum: cada tanque ligava a morte de alguém a um registro. As duas portas sul foram despedaçadas; entre a oficina e a Sala 35 há agora um túnel largo, deformado por impacto, com vigas mordidas, placas processuais quebradas e marcas do corpo do tubarão nas paredes.","Pressão / Encontro":"Os tanques projetam afogamentos personalizados. Uma vítima ilusória sempre possui o rosto de alguém que o observador acredita ter abandonado. As cintas, porém, são reais e podem prender quem tentar resgatar a visão sem investigar.","Pista concreta (sem teste)":"Sem teste, após observar um tanque por uma rodada: alguns mortos aceitaram tornar-se testemunhas para preservar nomes e crimes. O Arquivo foi construído tanto como mausoléu quanto como instituição de prova.","Interações relevantes":"Os tanques ainda reagem a nomes pronunciados. As duas portas do sul e o corredor até a sala 35 foram triturados pelo tubarão gigante, deixando um túnel largo de pedras soltas e vigas mordidas.","Tesouro / recompensa":"Pinça de Registro Vital, ferramenta rara. Uma vez por descanso longo, estabiliza automaticamente uma criatura a 0 PV tocada e grava seu nome numa lâmina de metal.","Colecionável":"Conjunto de 8 etiquetas ósseas intactas (50 PO cada) e Fragmento do Juramento IV.","Armadilha de ilusão":"Um tanque mostra um aliado se afogando. Sabedoria CD 17; falha: a criatura gasta movimento e ação tentando resgatá-lo e fica restringida pelas cintas reais do tanque. Atletismo CD 16 para escapar."},"doors":[{"to":28,"face":"Norte · P57","attrs":"trancada (CD 20 para destrancar); madeira simples; CD 15 para arrombar; 10 PV","status":"DESTRUÍDA pelo tubarão gigante; acesso 28–32 permanece aberto.","id":"P57","broken":true,"secret":false,"trap":false,"dc":20},{"to":35,"face":"Sul · P62","attrs":"trancada (CD 20 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"DESTRUÍDA pelo tubarão gigante; corredor 32–35 também demolido. Passagem aberta, ruidosa e coberta de detritos.","id":"P62","broken":true,"secret":false,"trap":false,"dc":20},{"to":35,"face":"Sul · P63","attrs":"trancada (CD 20 para destrancar); pedra; CD 25 para arrombar; 60 PV","status":"DESTRUÍDA pelo tubarão gigante; corredor 32–35 também demolido. Passagem aberta, ruidosa e coberta de detritos.","id":"P63","broken":true,"secret":false,"trap":false,"dc":20},{"to":27,"face":"Oeste · P55","attrs":"armadilhada; destrancada; madeira reforçada; 20 PV","status":"Intacta conforme o mapa original.","id":"P55","broken":false,"secret":false,"trap":true,"dc":0}]},"33":{"id":33,"name":"Quarto dos Juramentos Quebrados","xy":[168,520],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Arquivo de promessas traídas.","Descrição":"Faixas, selos e fragmentos de fala ecoam como se juramentos ainda apodrecessem nas paredes.","Pressão / Encontro":"Espaço perfeito para demônios manipularem culpa e ressentimento; jogadas sociais podem sofrer distorção.","Pista concreta (sem teste)":"O Arquivo diferencia juramento rompido por covardia e juramento rompido para negar um poder ilegítimo.","Interações relevantes":"Selos podem ser reunidos e queimados para mostrar qual promessa foi quebrada.","Tesouro / recompensa":"Fita do Juramento Quebrado. 1/dia, vantagem para detectar mentira numa promessa feita diante do usuário.","Colecionável":"20 lacres nobres históricos (500 PO o lote).","Armadilha de ilusão":"Uma voz acusa cada personagem de quebrar seu maior compromisso. Carisma CD 17; falha: 4d6 psíquico e não pode falar por 1 rodada."},"doors":[{"to":30,"face":"Norte · P61","attrs":"armadilhada; trancada (CD 15 para destrancar); pedra; CD 25 para arrombar; 60 PV; desliza lateralmente","status":"Intacta conforme o mapa original.","id":"P61","broken":false,"secret":false,"trap":true,"dc":15},{"to":36,"face":"Leste · P65","attrs":"trancada (CD 10 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P65","broken":false,"secret":false,"trap":false,"dc":10}]},"34":{"id":34,"name":"Scriptorium do Sonho","xy":[520,520],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Centro menor de escrita e imaginação ordenadora.","Descrição":"Superfícies de escrita em osso e pedra cercam uma mesa baixa quase intacta.","Pressão / Encontro":"Quem escrever ou desenhar aqui pode acionar efeito breve de criação, revelação ou mentira magnificada.","Pista concreta (sem teste)":"A palavra ‘Sonho’ aqui não significa fantasia vazia, mas projeto de ordem possível para a Carcaça.","Interações relevantes":"A mesa produz escrita quando recebe uma gota de tinta ritual ou sangue voluntário.","Tesouro / recompensa":"Estilete do Sonho Ordenado +1, adaga/foco. 1/dia, lança Escrita Ilusória sem componente.","Colecionável":"Selo da Foz XII? (reservado para 13) — aqui, 5 folhas de osso fino, 100 PO cada.","Armadilha de ilusão":"O texto escreve o próximo movimento do leitor. Inteligência CD 18; falha: deve realizar a ação descrita no turno seguinte se possível."},"doors":[{"to":34,"face":"Norte · P70","attrs":"trancada (CD 20 para destrancar); pedra; CD 25 para arrombar; 60 PV","status":"Intacta conforme o mapa original.","id":"P70","broken":false,"secret":false,"trap":false,"dc":20},{"to":34,"face":"Norte · P71","attrs":"armadilhada; trancada (CD 20 para destrancar); pedra; CD 25 para arrombar; 60 PV; desliza lateralmente","status":"Intacta conforme o mapa original.","id":"P71","broken":false,"secret":false,"trap":true,"dc":20},{"to":35,"face":"Leste · P69","attrs":"trancada (CD 15 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P69","broken":false,"secret":false,"trap":false,"dc":15},{"to":40,"face":"Sul · P68","attrs":"trancada (CD 15 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P68","broken":false,"secret":false,"trap":false,"dc":15},{"to":37,"face":"Oeste · P66","attrs":"secreta (CD 25 para encontrar); armadilhada; trancada (CD 10 para destrancar); ferro; CD 30 para arrombar; 60 PV; desliza lateralmente","status":"Intacta conforme o mapa original.","id":"P66","broken":false,"secret":true,"trap":true,"dc":10},{"to":38,"face":"Oeste · P67","attrs":"trancada (CD 20 para destrancar); madeira simples; CD 15 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P67","broken":false,"secret":false,"trap":false,"dc":20}]},"35":{"id":35,"name":"Ante-Templo da Foz","xy":[616,520],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Vestíbulo cerimonial anterior ao núcleo político da foz.","Descrição":"Colunas de pedra verde sustentam um teto cerimonial coberto por nomes de regentes, juízes e guardiões. Faixas aquáticas se movem como bandeiras, embora não exista corrente. O acesso leste vindo da Sala 32 foi escancarado pela destruição do corredor; ao sul, a antiga porta para a Sala 41 foi arrancada e seus gonzos parecem dedos quebrados.","Pressão / Encontro":"A sala tenta transformar qualquer presença em cerimônia. Figuras de autoridade aparecem como convidados, testemunhas e súditos. A ilusão é perigosa porque oferece legitimidade, não medo.","Pista concreta (sem teste)":"Sem teste: nenhum nome élfico aparece entre os títulos mais antigos. A autoridade da foz precede a Rainha da Noite, Ulorian e a conquista shadow fey.","Interações relevantes":"As colunas ainda projetam nomes de antigos regentes quando tocadas. O corredor leste vindo da sala 32 foi devastado; a porta sul para a sala 41 foi arrancada, deixando gonzos retorcidos e uma boca escura.","Tesouro / recompensa":"Coroa Cerimonial da Foz, não mágica, 1.200 PO; usada diante de yokai, concede vantagem em um teste de Persuasão para pedir audiência, não obediência.","Colecionável":"Fragmento do Juramento V e duas faixas processionais de seda aquática (250 PO cada).","Armadilha de ilusão":"Uma cerimônia proclama Ulorian como escolhido legítimo. História ou Religião CD 18 nota títulos anacrônicos. Falha: o observador aceita a cena como memória real até confrontado por prova física."},"doors":[{"to":32,"face":"Leste · P73","attrs":"trancada (CD 10 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"DESTRUÍDA pelo tubarão gigante; corredor 32–35 também demolido. Passagem aberta, ruidosa e coberta de detritos.","id":"P73","broken":true,"secret":false,"trap":false,"dc":10},{"to":41,"face":"Sul · P72","attrs":"armadilhada; trancada (CD 10 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"DESTRUÍDA pelo tubarão gigante; acesso 35–41 permanece aberto.","id":"P72","broken":true,"secret":false,"trap":true,"dc":10},{"to":34,"face":"Oeste · P69","attrs":"trancada (CD 15 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P69","broken":false,"secret":false,"trap":false,"dc":15}]},"36":{"id":36,"name":"Maré de Lodo Vivo","xy":[264,552],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Zona hostil de mobilidade e desgaste.","Descrição":"Lodo espesso, água baixa e correntes imprevisíveis formam uma sala fisicamente desagradável.","Pressão / Encontro":"Lampreias, armadilha de sucção, teias úmidas ou ataques de puxão funcionam muito bem aqui.","Pista concreta (sem teste)":"Marcas de barriga e cauda sugerem trânsito frequente de Gharoz ou de algo do seu porte.","Interações relevantes":"O lodo pode ser recolhido e usado para apagar rastros ou prender uma porta.","Tesouro / recompensa":"Lodo Vivo em jarro, 3 usos. Cria terreno difícil de 3 m por 1 minuto ou concede vantagem para apagar rastros.","Colecionável":"Nódulo de âmbar lodoso (350 PO).","Armadilha de ilusão":"A superfície parece firme. Percepção CD 16; falha: afunda, fica restringido e sofre 2d8 ácido por rodada."},"doors":[{"to":29,"face":"Norte · P59","attrs":"secreta (CD 15 para encontrar); destrancada; madeira simples; 10 PV","status":"Intacta conforme o mapa original.","id":"P59","broken":false,"secret":true,"trap":false,"dc":0},{"to":39,"face":"Sul · P74","attrs":"armadilhada; destrancada; madeira de boa qualidade; 15 PV","status":"Intacta conforme o mapa original.","id":"P74","broken":false,"secret":false,"trap":true,"dc":0},{"to":42,"face":"Sul · P75","attrs":"secreta (CD 25 para encontrar); destrancada; madeira simples; 10 PV","status":"Intacta conforme o mapa original.","id":"P75","broken":false,"secret":true,"trap":false,"dc":0},{"to":33,"face":"Oeste · P65","attrs":"trancada (CD 10 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P65","broken":false,"secret":false,"trap":false,"dc":10}]},"37":{"id":37,"name":"Câmara do Peso e da Escolha","xy":[360,536],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Sala de decisão simbólica.","Descrição":"Pratos, contrapesos e linhas rituais fazem parecer que a própria sala mede intenção e custo.","Pressão / Encontro":"Pode exigir escolha concreta — largar algo, assumir algo, revelar algo — para abrir rota ou diminuir pressão do Arquivo.","Pista concreta (sem teste)":"O lugar reforça que a Lança não foi feita para mãos neutras no vazio; foi feita para alguém disposto a pagar um preço político real.","Interações relevantes":"Os pratos aceitam objetos, memórias declaradas ou promessas. O peso correto revela uma rota curta.","Tesouro / recompensa":"Balança da Escolha, item raro de uso narrativo: 1/dia indica qual de duas opções declaradas exige maior sacrifício pessoal, não qual é melhor.","Colecionável":"Selo da Foz — peça substituta de chumbo, 200 PO.","Armadilha de ilusão":"Um prato mostra um custo inexistente. Intuição CD 18; falha: personagem sacrifica temporariamente um recurso à escolha do mestre até descanso curto."},"doors":[{"to":34,"face":"Leste · P77","attrs":"trancada (CD 25 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P77","broken":false,"secret":false,"trap":false,"dc":25},{"to":39,"face":"Sul · P76","attrs":"secreta (CD 20 para encontrar); emperrada; madeira simples; CD 10 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P76","broken":false,"secret":true,"trap":false,"dc":12}]},"38":{"id":38,"name":"Ruptura de Morgat","xy":[424,584],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Área preferencial do tenente bruto demoníaco.","Descrição":"Paredes estilhaçadas, correntes arrancadas, suporte colapsado e água revolvida por violência repetida.","Pressão / Encontro":"Morgat, Quebra-Âncoras do Vazio (CR 11), ou evidência clara de que ele está forçando passagem para setores mais internos.","Pista concreta (sem teste)":"Os demônios não entendem o Arquivo como os yokai, mas já aprenderam quais estruturas precisam quebrar para pressioná-lo.","Interações relevantes":"As marcas de impacto permitem prever como Morgat luta e quais paredes ele já enfraqueceu.","Tesouro / recompensa":"Manilha Quebra-Âncoras, bracelete +1 em Atletismo; 1/dia, dobra dano contra objeto ou estrutura.","Colecionável":"Pedaço de chifre de Morgat (450 PO).","Armadilha de ilusão":"A parede parece desabar. Destreza CD 17; falha: mergulha para uma posição ruim e fica caído/restringido sob correntes ilusórias."},"doors":[{"to":34,"face":"Leste · P67","attrs":"trancada (CD 20 para destrancar); madeira simples; CD 15 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P67","broken":false,"secret":false,"trap":false,"dc":20},{"to":40,"face":"Leste · P78","attrs":"trancada (CD 15 para destrancar); ferro; CD 30 para arrombar; 60 PV; reforçada magicamente; desvantagem para arrombar","status":"Intacta conforme o mapa original.","id":"P78","broken":false,"secret":false,"trap":false,"dc":15}]},"39":{"id":39,"name":"Câmara do Convite Partido","xy":[360,632],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Lugar onde o Arquivo e o Abismo parecem oferecer ajuda ao mesmo tempo.","Descrição":"A sala parece duas versões de si mesma: uma promissora, outra afogada, sem que nenhuma se imponha totalmente.","Pressão / Encontro":"Excelente para reaparição de Veren se o grupo evitou as antessalas ou para reforçar sua narrativa de abandono pelos elfos.","Pista concreta (sem teste)":"As ofertas mais tentadoras do Arquivo e do Abismo quase nunca coincidem; quando coincidem, há custo escondido.","Interações relevantes":"Responder em voz alta qual ajuda se aceita faz uma das duas versões da sala prevalecer.","Tesouro / recompensa":"Convite Partido, carta mágica em duas metades. Rasgar uma metade concede vantagem num teste social com yokai ou demônio; cada metade funciona uma vez.","Colecionável":"Fragmento do Juramento VI.","Armadilha de ilusão":"O Arquivo e o Abismo oferecem o mesmo rosto. Intuição CD 18; falha: aceita um benefício ilusório e sofre 5d6 psíquico ao descobrir o custo."},"doors":[{"to":37,"face":"Norte · P76","attrs":"secreta (CD 20 para encontrar); emperrada; madeira simples; CD 10 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P76","broken":false,"secret":true,"trap":false,"dc":12},{"to":36,"face":"Oeste · P79","attrs":"armadilhada; emperrada; madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P79","broken":false,"secret":false,"trap":true,"dc":12},{"to":42,"face":"Oeste · P80","attrs":"secreta (CD 15 para encontrar); emperrada; madeira simples; CD 10 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P80","broken":false,"secret":true,"trap":false,"dc":12}]},"40":{"id":40,"name":"Boca do Sonho Podre","xy":[520,648],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Território principal de Gharoz.","Descrição":"Um lago interno ocupa quase toda a câmara. A água é negra, oleosa e funda demais para o tamanho aparente da sala. Colunas partidas somem na escuridão abaixo, e bolhas grandes sobem sem estourar. A rota leste, vinda da Sala 41, foi rasgada pelo tubarão gigante e oferece uma entrada larga, coberta de escombros. Gharoz não está ferido: ele apenas permitiu que os invasores percebessem sua escala antes de aparecer com o Morgat.","Pressão / Encontro":"Gharoz, o Crocodilo Gordo do Sonho Podre (CR 14), está em plena capacidade e luta em território preparado. O Morgat usa paredes, fossos e correntes para separar alvos. Lampreias podem emergir das colunas. A primeira ilusão faz parecer que Gharoz atacará de uma direção; a segunda transforma uma bolsa sem ar em rota de fuga.","Pista concreta (sem teste)":"Sem teste, ao ver o Berrante Aquático: o objeto é um chamado, não uma chave de força. Gharoz pode carregá-lo, mas não consegue produzir sozinho a intenção sem lealdade obscura capaz de enganar Jorō.","Interações relevantes":"A água negra revela a passagem de Gharoz por ondas sem vento. O corredor leste vindo da sala 41 foi arrebentado; pedras, dentes e lascas formam uma rota larga, mas ruidosa.","Tesouro / recompensa":"Berrante Aquático, em posse de Gharoz. Além de seu uso ritual, pode lançar Controlar Água 1/dia após ser purificado. Tesouro secundário: 2.000 PO em oferendas engolidas e acumuladas no fundo.","Colecionável":"Dente de Gharoz gravado com uma runa abissal, 750 PO ou componente de banimento.","Armadilha de ilusão":"A boca de Gharoz parece surgir de qualquer sombra. Percepção CD 18; falha: reação desperdiçada e desvantagem no primeiro ataque real contra ele. Uma segunda ilusão simula uma rota de fuga que termina num bolsão sem ar."},"doors":[{"to":34,"face":"Norte · P68","attrs":"trancada (CD 15 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"Intacta conforme o mapa original.","id":"P68","broken":false,"secret":false,"trap":false,"dc":15},{"to":41,"face":"Leste · P83","attrs":"trancada (CD 15 para destrancar); pedra; CD 25 para arrombar; 60 PV","status":"DESTRUÍDA pelo tubarão gigante; corredor 41–40 também foi rasgado. Passagem aberta, com escombros.","id":"P83","broken":true,"secret":false,"trap":false,"dc":15},{"to":38,"face":"Oeste · P78","attrs":"trancada (CD 15 para destrancar); ferro; CD 30 para arrombar; 60 PV; reforçada magicamente; desvantagem para arrombar","status":"Intacta conforme o mapa original.","id":"P78","broken":false,"secret":false,"trap":false,"dc":15},{"to":43,"face":"Oeste · P81","attrs":"trancada (CD 15 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P81","broken":false,"secret":false,"trap":false,"dc":15}]},"41":{"id":41,"name":"Altar do Trono Vazio","xy":[616,616],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Restante simbólico do comando da foz.","Descrição":"Um altar baixo ocupa o centro, cercado por um espaço vazio onde um trono deveria existir. O piso possui sulcos para água correr em direção a um ocupante ausente. A porta norte para a Sala 35 está destruída; ao sul, a rota demolida pelo tubarão abre caminho torto até a Sala 40. Insígnias antigas foram deliberadamente viradas para baixo, como se o próprio Arquivo se recusasse a reconhecer um sucessor.","Pressão / Encontro":"O altar mostra poder sem legitimidade. Quem o toca vê o posto que mais deseja ocupar e o preço que finge não conhecer. A visão tenta arrancar uma declaração pública.","Pista concreta (sem teste)":"Sem teste: Ulorian ocupa o posto material de Rei do Rio e sente suas correntes, mas ainda não domina a linguagem ritual que converte domínio em regência reconhecida.","Interações relevantes":"O altar responde a quem declara que posto deseja e qual preço aceita. A porta norte para 35 e a rota sul/leste para 40 estão destruídas pelo tubarão gigante.","Tesouro / recompensa":"Selo do Trono Vazio, broche raro. 1/dia, ao recusar uma ordem de autoridade, recebe 10 PV temporários e vantagem no próximo teste de resistência contra encantamento.","Colecionável":"Insígnia do último Regente reconhecido pelo Arquivo (1.000 PO, valor político muito maior).","Armadilha de ilusão":"Um trono de água oferece poder imediato. Carisma CD 19; falha: o personagem se ajoelha e revela em voz alta quem gostaria de governar."},"doors":[{"to":35,"face":"Norte · P72","attrs":"armadilhada; trancada (CD 10 para destrancar); madeira de boa qualidade; CD 15 para arrombar; 15 PV","status":"DESTRUÍDA pelo tubarão gigante; acesso 35–41 permanece aberto.","id":"P72","broken":true,"secret":false,"trap":true,"dc":10},{"to":40,"face":"Sul · P85","attrs":"armadilhada; trancada (CD 15 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"DESTRUÍDA pelo tubarão gigante; corredor 41–40 também foi rasgado. Passagem aberta, com escombros.","id":"P85","broken":true,"secret":false,"trap":true,"dc":15}]},"42":{"id":42,"name":"Teia Submersa sem Rainha","xy":[248,648],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Campo avançado de teias e ecos da Jorō, não a sala dela.","Descrição":"Teias líquidas descem do teto e se confundem com água suspensa.","Pressão / Encontro":"Excelente para emboscada yokai, proteção de rota ou aviso de que o Arquivo ainda está julgando os intrusos.","Pista concreta (sem teste)":"A presença da aranha não se limita à Room 13; sua atenção percorre o Arquivo inteiro por meio de água, reflexo e teia.","Interações relevantes":"As teias transmitem gestos e emoções até Jorō. Cortá-las é percebido como agressão; tocá-las com cuidado envia uma impressão.","Tesouro / recompensa":"Fio de Teia Submersa, 3 usos. Reação: reduz dano de queda ou deslocamento forçado a zero e ancora o usuário.","Colecionável":"Casulo com três pérolas cinzentas (300 PO cada).","Armadilha de ilusão":"Uma aranha gigantesca parece atacar. Intuição CD 18 reconhece que ela protege uma rota. Falha: o alvo foge para a direção escolhida pela teia."},"doors":[{"to":36,"face":"Norte · P75","attrs":"secreta (CD 25 para encontrar); destrancada; madeira simples; 10 PV","status":"Intacta conforme o mapa original.","id":"P75","broken":false,"secret":true,"trap":false,"dc":0},{"to":39,"face":"Leste · P88","attrs":"armadilhada; destrancada; madeira simples; 10 PV","status":"Intacta conforme o mapa original.","id":"P88","broken":false,"secret":false,"trap":true,"dc":0},{"to":43,"face":"Sul · P86","attrs":"secreta (CD 15 para encontrar); destrancada; madeira reforçada; 20 PV","status":"Intacta conforme o mapa original.","id":"P86","broken":false,"secret":true,"trap":false,"dc":0}]},"43":{"id":43,"name":"Mirante da Foz Perdida","xy":[424,680],"fields":{"Estado hídrico":"Completamente submersa. A sala exige nado, travessia aquática, deslocamento mágico, adaptação anfíbia ou soluções equivalentes.","Função":"Sala de observação e revelação tardia.","Descrição":"Uma abertura alta permite ver parte do complexo como se o Arquivo fosse uma cidade afundada em miniatura.","Pressão / Encontro":"Bom lugar para reorganizar rota, compreender conexões e perceber que não existe caminho único até a Lança.","Pista concreta (sem teste)":"A arquitetura inteira reforça a leitura correta do mapa: começo e fim são fixos; o resto é exploração, prova e escolha.","Interações relevantes":"O mirante permite traçar rotas. Marcar uma sala no mapa faz a água mostrar a conexão mais curta ainda transitável.","Tesouro / recompensa":"Mapa Vivo da Foz Perdida. 1/dia, revela a rota mais curta para uma sala conhecida do Arquivo, considerando portas e desabamentos atuais.","Colecionável":"Miniatura de Gualápoles em cristal fluvial (1.500 PO).","Armadilha de ilusão":"A miniatura mostra uma rota perfeita que não existe. Investigação CD 17; falha: o mapa leva a uma porta secreta falsa e desperdiça 20 minutos."},"doors":[{"to":40,"face":"Leste · P81","attrs":"trancada (CD 15 para destrancar); madeira reforçada; CD 20 para arrombar; 20 PV","status":"Intacta conforme o mapa original.","id":"P81","broken":false,"secret":false,"trap":false,"dc":15},{"to":42,"face":"Oeste · P89","attrs":"trancada (CD 25 para destrancar); madeira simples; CD 15 para arrombar; 10 PV","status":"Intacta conforme o mapa original.","id":"P89","broken":false,"secret":false,"trap":false,"dc":25}]}};
